import{_ as t,o as s,c as i,ag as o}from"./chunks/framework.DMVuHR7L.js";const g=JSON.parse('{"title":"Deployment","description":"","frontmatter":{},"headers":[],"relativePath":"devs/deployment.md","filePath":"devs/deployment.md","lastUpdated":1778670471000}'),a={name:"devs/deployment.md"};function n(d,e,r,l,h,p){return s(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h1><h2 id="topology" tabindex="-1">Topology <a class="header-anchor" href="#topology" aria-label="Permalink to &quot;Topology&quot;">​</a></h2><p>GitHub Pages, two environments served from the same Pages site:</p><table tabindex="0"><thead><tr><th>Environment</th><th>App URL</th><th>Docs URL</th><th>Source branch</th><th>Triggered by</th></tr></thead><tbody><tr><td>Staging</td><td><code>https://&lt;owner&gt;.github.io/web-logcat/staging/</code></td><td><code>https://&lt;owner&gt;.github.io/web-logcat/staging/docs/</code></td><td><code>main</code></td><td>every push</td></tr><tr><td>Production</td><td><code>https://&lt;owner&gt;.github.io/web-logcat/</code></td><td><code>https://&lt;owner&gt;.github.io/web-logcat/docs/</code></td><td><code>release</code></td><td>every push / merge</td></tr></tbody></table><p>Both environments are HTTPS by default — required for WebUSB. The docs site is a separate <a href="https://vitepress.dev/" target="_blank" rel="noreferrer">VitePress</a> app emitted into <code>dist/docs/</code>, so it ships in the same publish step as the main app.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>The <code>gh-pages</code> branch is the published-site source of truth. <a href="https://github.com/peaceiris/actions-gh-pages" target="_blank" rel="noreferrer"><code>peaceiris/actions-gh-pages</code></a> writes into a subdirectory keyed by the triggering branch:</p><ul><li>Push to <code>main</code> → build the app with <code>BASE_PATH=/web-logcat/staging/</code> and the docs with <code>DOCS_BASE_PATH=/web-logcat/staging/docs/</code> → deploy to <code>gh-pages:/staging/</code>. <code>keep_files: false</code> so stale staging assets are cleaned. The branch root is untouched.</li><li>Push to <code>release</code> → build the app with <code>BASE_PATH=/web-logcat/</code> and the docs with <code>DOCS_BASE_PATH=/web-logcat/docs/</code> → deploy to <code>gh-pages:/</code> (root). <code>keep_files: true</code> so the existing <code>/staging/</code> subtree is preserved. Stale production assets aren&#39;t pruned, but Vite&#39;s hashed filenames keep the bloat bounded.</li></ul><p>Both builds happen via <code>npm run build:all</code>, which runs the app build followed by the docs build. The docs output lands at <code>dist/docs/</code>, which the publish step picks up alongside the rest of <code>dist/</code>.</p><p>Workflow lives in <a href="https://github.com/gabrielhuff/web-logcat/blob/main/.github/workflows/deploy.yml" target="_blank" rel="noreferrer"><code>.github/workflows/deploy.yml</code></a>.</p><h2 id="one-time-setup" tabindex="-1">One-time setup <a class="header-anchor" href="#one-time-setup" aria-label="Permalink to &quot;One-time setup&quot;">​</a></h2><p>In the repo&#39;s GitHub UI:</p><ol><li><strong>Settings → Pages</strong><ul><li>Build and deployment → Source = <strong>Deploy from a branch</strong></li><li>Branch = <code>gh-pages</code>, folder = <code>/</code> (root). Save.</li></ul></li><li>The first <code>main</code> push will create the <code>gh-pages</code> branch and populate <code>/staging/</code>. The first <code>release</code> push will populate the root.</li><li>(Optional) <strong>Settings → Environments</strong> → add <code>staging</code> and <code>production</code> environments. Add manual approval to <code>production</code> if desired.</li></ol><h2 id="promoting-staging-→-production" tabindex="-1">Promoting staging → production <a class="header-anchor" href="#promoting-staging-→-production" aria-label="Permalink to &quot;Promoting staging → production&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ff-only</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release</span></span></code></pre></div><p>If <code>release</code> doesn&#39;t exist yet:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release</span></span></code></pre></div><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li><strong>404 after first staging deploy</strong> — Pages can take a minute to build the first time. Check the Deploy workflow run; if it succeeded, wait.</li><li><strong>WebUSB chooser empty on the deployed site</strong> — make sure you&#39;re on HTTPS, the device is unlocked, USB debugging is enabled, and you&#39;ve accepted the on-device authorisation prompt.</li><li><strong>Stale prod assets piling up</strong> — once a year (or whenever it bothers someone), force-rebuild prod with a clean tree by deleting <code>gh-pages</code> branch and re-running both deploys.</li><li><strong>Docs 404 after a rename</strong> — VitePress&#39;s <code>cleanUrls</code> strips the <code>.html</code> suffix in URLs. If you renamed a feature page, sweep the inbound links and re-deploy; the previous URL won&#39;t redirect.</li></ul><h2 id="why-github-pages-and-not-x" tabindex="-1">Why GitHub Pages and not X? <a class="header-anchor" href="#why-github-pages-and-not-x" aria-label="Permalink to &quot;Why GitHub Pages and not X?&quot;">​</a></h2><ul><li><strong>Cost:</strong> $0 for public repos. Cloudflare Pages and Vercel hobby tiers are also $0 but they require a separate account and tie us to a vendor. Pages keeps everything inside GitHub.</li><li><strong>Preview environments per PR:</strong> not supported by Pages directly. We chose a <code>main → staging</code>, <code>release → production</code> split instead. If per-PR previews become important, switch to Cloudflare Pages (free, supports them out of the box) — the build artefact is the same.</li></ul>`,21)])])}const u=t(a,[["render",n]]);export{g as __pageData,u as default};
